      && verifier.VerifyField(tablePos, 4 /*KIND*/, 1 /*agrKind*/, 1, false)
      && verifier.VerifyString(tablePos, 6 /*SCHEMA_NAME*/, false)
      && verifier.VerifyString(tablePos, 8 /*SQL*/, false)
      && verifier.VerifyString(tablePos, 10 /*X_FIELD*/, false)
      && verifier.VerifyVectorOfStrings(tablePos, 12 /*Y_FIELDS*/, false)
      && verifier.VerifyField(tablePos, 14 /*X_IS_TIME*/, 1 /*bool*/, 1, false)
      && verifier.VerifyString(tablePos, 16 /*X_UNIT*/, false)
      && verifier.VerifyVectorOfTables(tablePos, 18 /*BINS*/, AGRBinVerify.Verify, false)
      && verifier.VerifyVectorOfTables(tablePos, 20 /*CATEGORIES*/, AGRCategoryVerify.Verify, false)
      && verifier.VerifyVectorOfTables(tablePos, 22 /*SERIES*/, AGRSeriesVerify.Verify, false)
      && verifier.VerifyVectorOfTables(tablePos, 24 /*PIVOT*/, AGRPivotCellVerify.Verify, false)
      && verifier.VerifyVectorOfStrings(tablePos, 26 /*ROW_KEYS*/, false)
      && verifier.VerifyVectorOfStrings(tablePos, 28 /*COL_KEYS*/, false)
      && verifier.VerifyField(tablePos, 30 /*SCANNED*/, 8 /*ulong*/, 8, false)
      && verifier.VerifyField(tablePos, 32 /*MATCHED*/, 8 /*ulong*/, 8, false)
      && verifier.VerifyField(tablePos, 34 /*STORED*/, 8 /*ulong*/, 8, false)
      && verifier.VerifyField(tablePos, 36 /*PARTIAL*/, 1 /*bool*/, 1, false)
      && verifier.VerifyField(tablePos, 38 /*TRUNCATED*/, 1 /*bool*/, 1, false)
      && verifier.VerifyField(tablePos, 40 /*ELAPSED_MS*/, 4 /*uint*/, 4, false)
      && verifier.VerifyField(tablePos, 42 /*AS_OF_MS*/, 8 /*long*/, 8, false)
      && verifier.VerifyString(tablePos, 44 /*PROVIDER_ID*/, false)
